parameters.jsCode:
const item = $json;

    // 1. Title Sanitizer (Max 35 chars)
    let title = (item.title || '').trim();
    if (!title || title.startsWith('Product B0') || title.startsWith('Product ')) {
      title = (item.image_hook || item.pin_title || '').trim();
    }
    if (title.length > 35) {
      const words = title.split(' ');
      let shortW = [];
      let cLen = 0;
      for (const w of words) {
        if (cLen + w.length + 1 <= 35) {
          shortW.push(w);
          cLen += w.length + 1;
        } else break;
      }
      title = shortW.length > 0 ? shortW.join(' ') : title.substring(0, 35);
    }

    // 2. Price Sanitizer
    let price = (item.price || '').toString().trim();
    if (price.startsWith('.')) price = '$19' + price;
    if (price && !price.startsWith('$') && !/[₹£€¥]/.test(price)) price = '$' + price;

    return {
      json: {
        ...item,
        asin: item.asin,
        title: title,
        price: price,
        pin_title: item.pin_title || title,
        pin_description: item.pin_description || '',
        badge_hook: item.badge_hook || 'VIRAL ROOM FIND',
        chosen_photo_url: item.chosen_photo_url || item.winner_photo
      }
    };

